/**
 * Room ids are generated by the browser, not by the server: a room exists while somebody is in
 * it, so there is nothing to create before the first participant arrives. The id is a UUID,
 * which is what the service's route accepts, and the shared link is a page URL carrying it.
 *
 * The join field takes the id, the link this app copies, or any URL with a room query parameter,
 * because those are the three things people paste.
 */

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const ROOM_QUERY = /[?&]room=([0-9a-fA-F-]{36})/;

export function is_room_id(value: string): boolean {
  return UUID.test(value);
}

export function new_room_id(): string {
  return crypto.randomUUID();
}

export function room_id_from_input(input: string): string | null {
  const text = input.trim();
  if (text === "") return null;
  if (is_room_id(text)) return text.toLowerCase();

  // A relative path or query pasted from the address bar has no scheme, so URL parsing would
  // treat it as a path; the query is the part that matters in both forms.
  const query = ROOM_QUERY.exec(text);
  if (query !== null && query[1] !== undefined && is_room_id(query[1])) {
    return query[1].toLowerCase();
  }

  // Any other URL, as long as the id is its last path segment.
  try {
    const url = new URL(text, "http://room.invalid");
    const last = url.pathname.split("/").filter((part) => part !== "").pop();
    if (last !== undefined && is_room_id(last)) return last.toLowerCase();
  } catch {
    return null;
  }
  return null;
}

/** The link this app copies for an invitation. */
export function share_url(room_id: string, origin: string): string {
  return `${origin.replace(/\/$/, "")}/videocall/?room=${encodeURIComponent(room_id)}`;
}
